module kth_sequence(\n    input wire clk,\n    input wire rst_n,\n    input wire start,\n    input wire [3:0] n,\n    input wire [13:0] k,\n    output reg [2:0] seq_0, seq_1, seq_2, seq_3, seq_4, seq_5, seq_6, seq_7,\n    output reg done\n);\n\n    // State definitions\n    localparam [2:0] IDLE    = 3'd0;\n    localparam [2:0] FIND_A  = 3'd1;\n    localparam [2:0] UPDATE  = 3'd2;\n    localparam [2:0] NEXT    = 3'd3;\n    localparam [2:0] DONE_ST = 3'd4;\n\n    // Internal registers\n    reg [2:0] state;\n    reg [3:0] s;\n    reg [7:0] used;\n    reg [3:0] i;\n    reg [13:0] rem_k;\n    reg [3:0] a;\n\n    // Combinational logic\n    wire [3:0] new_s_temp = s + a;\n    wire [3:0] new_s = (new_s_temp >= n) ? new_s_temp - n : new_s_temp;\n    wire valid = (used[new_s] == 1'b0);\n\n    // Factorial lookup table\n    reg [13:0] count_per;\n    always @(*) begin\n        case (n - i - 1)\n            4'd0: count_per = 14'd1;\n            4'd1: count_per = 14'd1;\n            4'd2: count_per = 14'd2;\n            4'd3: count_per = 14'd6;\n            4'd4: count_per = 14'd24;\n            4'd5: count_per = 14'd120;\n            4'd6: count_per = 14'd720;\n            default: count_per = 14'd0;\n        endcase\n    end\n\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            state <= IDLE;\n            done <= 1'b0;\n            seq_0 <= 3'd0;\n            seq_1 <= 3'd0;\n            seq_2 <= 3'd0;\n            seq_3 <= 3'd0;\n            seq_4 <= 3'd0;\n            seq_5 <= 3'd0;\n            seq_6 <= 3'd0;\n            seq_7 <= 3'd0;\n            s <= 4'd0;\n            used <= 8'd0;\n            i <= 4'd0;\n            rem_k <= 14'd0;\n            a <= 4'd0;\n        end else begin\n            case (state)\n                IDLE: begin\n                    done <= 1'b0;\n                    if (start) begin\n                        s <= 4'd0;\n                        used <= 8'b00000001;\n                        i <= 4'd1;\n                        rem_k <= k;\n                        a <= 4'd1;\n                        state <= FIND_A;\n                    end\n                end\n\n                FIND_A: begin\n                    if (valid) begin\n                        if (rem_k > count_per) begin\n                            rem_k <= rem_k - count_per;\n                            a <= a + 4'd1;\n                        end else begin\n                            state <= UPDATE;\n                        end\n                    end else begin\n                        a <= a + 4'd1;\n                    end\n                end\n\n                UPDATE: begin\n                    case (i)\n                        4'd1: seq_0 <= a[2:0];\n                        4'd2: seq_1 <= a[2:0];\n                        4'd3: seq_2 <= a[2:0];\n                        4'd4: seq_3 <= a[2:0];\n                        4'd5: seq_4 <= a[2:0];\n                        4'd6: seq_5 <= a[2:0];\n                        4'd7: seq_6 <= a[2:0];\n                        4'd8: seq_7 <= a[2:0];\n                    endcase\n                    s <= new_s;\n                    used <= used | (8'd1 << new_s);\n                    state <= NEXT;\n                end\n\n                NEXT: begin\n                    i <= i + 4'd1;\n                    if (i >= n - 4'd1) begin\n                        state <= DONE_ST;\n                    end else begin\n                        a <= 4'd1;\n                        state <= FIND_A;\n                    end\n                end\n\n                DONE_ST: begin\n                    done <= 1'b1;\n                    state <= IDLE;\n                end\n\n                default: state <= IDLE;\n            endcase\n        end\n    end\nendmodule